const DATABASE_ID_PREFIX = 'db_'

/**
 * `$ prisma postgres link`
 *
 * Links a local project to a Prisma Postgres database by writing the connection
 * string to the project's `.env` file.
 */
export class Link {
  public static new(): Link {
    return new Link()
  }

  private static help = format(`
Link a local project to a Prisma Postgres database.

${bold('Usage')}

  ${dim('$')} prisma postgres link [options]

${bold('Options')}

  -h, --help       Display this help message
    --api-key      A Prisma Postgres API key (enables non-interactive mode)
    --database     The ID of the database to link (e.g. db_xxx)
    --force        Re-link even if the project is already linked

${bold('Examples')}

  Link interactively (browser-based authentication)
    ${dim('$')} prisma postgres link

  Link non-interactively with an API key
    ${dim('$')} prisma postgres link --api-key <key> --database db_xxx
`)

  public async parse(
    argv: string[],
    config: unknown,
    cwd: string = process.cwd(),
  ): Promise<string | HelpError | Error> {
    const args = arg(argv, {
      '--help': Boolean,
      '-h': '--help',
      '--api-key': String,
      '--database': String,
      '--force': Boolean,
    })

    if (isError(args)) {
      return this.help(args.message)
    }

    if (args['--help']) {
      return Link.help
    }

    const apiKeyFlag = args['--api-key']
    const database = args['--database']
    const force = Boolean(args['--force'])

    // `--api-key` is only meaningful together with `--database`.
    if (apiKeyFlag && !database) {
      return this.help('The `--database` option is required when `--api-key` is provided.')
    }

    // If the project is already linked, skip everything unless `--force` is set.
    if (!force && isAlreadyLinked(cwd)) {
      return `This project is already linked to a Prisma Postgres database.
Use ${bold('--force')} to re-link it to a different database.`
    }

    try {
      // Interactive mode: no `--api-key` and no `--database`.
      if (!apiKeyFlag && !database) {
        return await this.runInteractive(cwd, config)
      }

      // Non-interactive mode: `--database` is provided.
      return await this.runNonInteractive({ apiKeyFlag, database: database!, cwd, config })
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e)
      return this.help(sanitizeErrorMessage(message))
    }
  }

  private async runNonInteractive(opts: {
    apiKeyFlag?: string
    database: string
    cwd: string
    config: unknown
  }): Promise<string | HelpError> {
    const { apiKeyFlag, database, cwd, config } = opts

    if (!database.startsWith(DATABASE_ID_PREFIX)) {
      return this.help(
        `Invalid ${bold('--database')} value "${database}". A database ID must start with \`${DATABASE_ID_PREFIX}\`.`,
      )
    }

    const token = apiKeyFlag ?? process.env.PRISMA_API_KEY
    if (!token) {
