      )
    }

    const client = createManagementApiClient({ token })
    const connection = await createDevConnection(client, database)

    return this.finish(cwd, config, connection)
  }

  private async runInteractive(cwd: string, config: unknown): Promise<string | HelpError> {
    let sdk = createAuthenticatedManagementAPI()

